function nouveauJeu(avant){
	var jeu = monde.nouveauMonde({}, 4242, { avant: (DEJA ? "" : SOURCE) + "\n" + (avant || "") });
	jeu.lire("Object.keys(Shell.sorts).forEach(function(s){ state.spells[s] = true; state.usages[s] = true; }); state.set('sudoOK');" +
		"Shell.fin = function(){ if (typeof avancerToutesMachines === 'function') avancerToutesMachines(); Shell.narration = []; };");
	jeu.taper("cd ~");
	return jeu;
}
function poserFichiers(jeu){
	Object.keys(REFERENCES.fichiers).forEach(function(n){
		var f = REFERENCES.fichiers[n], texte = typeof f === "string" ? f : f.texte, latin = typeof f === "object" && f.latin1;
		jeu.lire("(function(){ var it = new Item(" + JSON.stringify(n) + ", " + JSON.stringify(texte.replace(/\n$/, "")) + "); it.owner = JOUEUR; " +
			(latin ? "it.encodage = 'ISO-8859-1';" : "") + (/\n$/.test(texte) ? "" : "it.sansFinDeLigne = true;") + " current_room.addItem(it); })()");
	});
}

/* --reel : relever les références avec les vrais outils (dans un dossier temporaire). */
if (reel){
	var cp = require("child_process"), os = require("os");
	var dossier = fs.mkdtempSync(path.join(os.tmpdir(), "donnees-"));
	var lancer = function(c, redir){
		fs.readdirSync(dossier).forEach(function(f){ fs.rmSync(path.join(dossier, f), { recursive: true, force: true }); });
		Object.keys(REFERENCES.fichiers).forEach(function(n){ var f = REFERENCES.fichiers[n], t = typeof f === "string" ? f : f.texte; fs.writeFileSync(path.join(dossier, n), typeof f === "object" && f.latin1 ? Buffer.from(t, "latin1") : t); });
		var r = cp.spawnSync("bash", ["-c", "{ " + c + "; } " + redir], { cwd: dossier, encoding: "utf8", env: Object.assign({}, process.env, { LC_ALL: "C" }) });
		return { s: r.stdout.replace(/\n$/, ""), code: r.status };
	};
	var differences = 0;
	REFERENCES.refs.forEach(function(x){ var r = lancer(x.c, "2>/dev/null"); if (r.s !== x.s || r.code !== x.code){ differences++; console.log("RÉFÉRENCE CHANGÉE : " + x.c + "\n" + r.s); } });
	console.log("--reel : " + REFERENCES.refs.length + " références relevées, " + differences + " ont changé.");
}

/* ================================================================== */
/* 1. Les sorties, comparées aux vrais outils                          */
/* ================================================================== */
REFERENCES.refs.forEach(function(x){
	var jeu = nouveauJeu();
	poserFichiers(jeu);
	var s = jeu.taper("{ " + x.c + "; } 2>/dev/null").replace(/\x1b\[[0-9;]*m/g, "");
	egal(s, x.s, "sortie de « " + x.c + " »");
	egal(jeu.lire("Shell.statut"), x.code, "code de retour de « " + x.c + " »");
	if (bavard) console.log("ok : " + x.c);
});

/* ================================================================== */
/* 2. Les messages d'erreur (les mêmes lignes)                          */
/* ================================================================== */
REFERENCES.erreurs.forEach(function(x){
	var jeu = nouveauJeu();
	poserFichiers(jeu);
	var s = jeu.taper("{ " + x.c + "; } 2>&1").replace(/\x1b\[[0-9;]*m/g, "");
	egal(s.split("\n").sort().join("\n"), x.s.split("\n").sort().join("\n"), "messages de « " + x.c + " »");
	egal(jeu.lire("Shell.statut"), x.code, "code de retour de « " + x.c + " »");
});

/* ================================================================== */
/* 3. Sur une machine modélisée                                        */
/* ================================================================== */
var G = 1073741824;
