Bief.racineHote = 'bief'; Bief.owner = 'root'; Bief.mode = 'rwxr-xr-x'; Bief.removeCommand('cd');
link_rooms(Machines, Bief);
decrireHote('bief', { ip: '10.0.97.77', ouvert: true, noyau: '6.12.9-amd64', arrivee: function(){ var m = Bief.getChildFromName('home'); m = m && m !== -1 ? m.getChildFromName(JOUEUR) : null; return m && m !== -1 ? m : Bief; } });
function fx(c, t, o){ o = o || {}; var it = poserFichierHote('bief', c, t, o); if (o.taille !== undefined) it.taille = o.taille; return it; }
var T0 = new Date(); T0.setHours(6, 0, 0, 0); T0 = T0.getTime();
['/etc', '/srv/lac', '/home', '/tmp', '/proc', '/run', '/root'].forEach(function(d){ creerDossierHote('bief', d); });
creerDossierHote('bief', '/home/' + JOUEUR, { owner: JOUEUR });
dossierHote('bief', '/tmp').mode = 'rwxrwxrwt';
