fx('/etc/passwd', ['root:x:0:0:root:/root:/bin/bash', JOUEUR + ':x:1000:1000::/home/' + JOUEUR + ':/bin/bash'].join('\\n'));
fx('/etc/group', ['root:x:0:', JOUEUR + ':x:1000:'].join('\\n'));
fx('/srv/lac/ingestion.lock', '');
