(function(){
	var jeu = nouveauJeu(FIXTURE);
	var t = function(l){ return jeu.taper(l).replace(/\x1b\[[0-9;]*m/g, ""); };
	var L = function(e){ return jeu.lire(e); };
	var code = function(){ return L("Shell.statut"); };
	contient(t("ssh bief"), "bief", "ssh bief");
	verifier(L("estMachine('bief')"), "bief est une machine modélisée");
	L("var DONNEES_VUS = []; GameEvents.addListener('donnees', function(e){ DONNEES_VUS.push(e.cmd); })");
	// ionice
	egal(t("ionice -p 4100"), "none: prio 0", "ionice -p : la classe de départ");
	egal(t("ionice -c 3 -p 4100"), "", "ionice -c 3 -p : silencieux");
	egal(t("ionice -p 4100"), "idle", "ionice -p : idle");
	egal(L("procParPid('bief', 4100).ionice.classe"), 3, "l'état du processus : classe 3");
	t("ionice -c2 -n7 -p 4100");
	egal(t("ionice -p 4100"), "best-effort: prio 7", "ionice -c2 -n7 : best-effort: prio 7");
	contient(t("ionice -c 1 -p 4100"), "ioprio_set failed: Operation not permitted", "realtime réservé à root");
	egal(code(), 1, "ionice -c 1 : code 1");
	contient(t("ionice -c 3 -p 4200"), "Operation not permitted", "le processus d'un autre, sans sudo");
	t("sudo ionice -c 3 -p 4200");
	egal(t("ionice -p 4200"), "idle", "sudo ionice sur le processus de root");
	contient(t("ionice -p 999"), "No such process", "ionice : pas de processus 999");
	egal(t("ionice -c 3 echo lancé"), "lancé", "ionice -c 3 COMMANDE : la commande tourne");
	// taskset
	egal(t("taskset -p 4100"), "pid 4100's current affinity mask: 3", "taskset -p : le masque (deux cœurs)");
	egal(t("taskset -cp 4100"), "pid 4100's current affinity list: 0,1", "taskset -cp : la liste");
	egal(t("taskset -cp 1 4100"), "pid 4100's current affinity list: 0,1\npid 4100's new affinity list: 1", "taskset -cp 1 PID");
	egal(L("JSON.stringify(procParPid('bief', 4100).affinite)"), "[1]", "l'affinité posée sur le processus");
	contient(t("taskset -cp 5 4100"), "Invalid argument", "un cœur qui n'existe pas");
	contient(t("taskset -cp 0 4200"), "Operation not permitted", "taskset sur le processus de root, sans sudo");
	egal(t("taskset -c 0 echo hop"), "hop", "taskset -c 0 COMMANDE");
	egal(t("taskset -p 1 4100").split("\n")[1], "pid 4100's new affinity mask: 1", "taskset -p MASQUE PID");
	// flock
	egal(t("flock -n /srv/lac/ingestion.lock echo jamais"), "", "flock -n : le verrou est tenu par ingestion, rien ne tourne");
	egal(code(), 1, "flock -n : code 1");
	t("flock -n -E 75 /srv/lac/ingestion.lock true");
	egal(code(), 75, "flock -E 75 : le code choisi");
	contient(t("flock /srv/lac/ingestion.lock echo jamais"), "4200", "flock sans -n : le jeu dit qui tient le verrou");
	egal(t("flock -n /tmp/ecluse.lock echo dedans"), "dedans", "flock -n sur un verrou libre");
	verifier(L("!!fichierHote('bief', '/tmp/ecluse.lock')"), "flock crée le fichier verrou");
	egal(t("flock -n /tmp/ecluse.lock flock -n /tmp/ecluse.lock echo deux"), "", "deux copies : la seconde abandonne");
	egal(t("flock -n /tmp/e.lock -c 'echo a; echo b'"), "a\nb", "flock -c 'ligne de shell'");
	// truncate sur un fichier fantôme
	contient(t("sudo lsof +L1"), "/srv/lac/ingestion.log (deleted)", "lsof +L1 montre le fichier fantôme");
	var avant = L("libreFs('bief', fsParCible('bief', '/')).utilise");
	contient(t("truncate -s 0 /proc/4200/fd/4"), "Permission denied", "truncate du fichier de root, sans sudo");
	egal(t("sudo truncate -s 0 /proc/4200/fd/4"), "", "sudo truncate -s 0 /proc/PID/fd/4");
	var apres = L("libreFs('bief', fsParCible('bief', '/')).utilise");
	verifier(avant - apres >= 3 * G - 4096, "la place du fichier fantôme est rendue (" + (avant - apres) + ")");
	contient(t("sudo truncate -s 0 /proc/4200/fd/9"), "No such file or directory", "un descripteur qui n'existe pas");
	// truncate d'un gros fichier
	var avantGros = L("libreFs('bief', fsParCible('bief', '/')).utilise");
	contient(t("truncate -s 0 /srv/lac/gros.log"), "Permission denied", "truncate du fichier de root, sans sudo");
	t("sudo truncate -s 0 /srv/lac/gros.log");
	verifier(avantGros - L("libreFs('bief', fsParCible('bief', '/')).utilise") >= 2 * G - 8192, "truncate -s 0 d'un fichier de 2 Gio rend la place");
	egal(L("fichierHote('bief', '/srv/lac/gros.log').taille"), 0, "gros.log fait 0 octet");
	t("sudo truncate -s 1G /srv/lac/gros.log");
	egal(L("fichierHote('bief', '/srv/lac/gros.log').taille"), G, "truncate -s 1G");
	// mktemp
	var tmp = t("mktemp").trim();
	verifier(/^\/tmp\/tmp\.[A-Za-z0-9]{10}$/.test(tmp), "mktemp : /tmp/tmp.XXXXXXXXXX (" + tmp + ")");
	contient(t("ls -l " + tmp), "-rw-------", "mktemp : un fichier que moi seul lis");
	var d = t("mktemp -d /tmp/ecluse.XXXXXX").trim();
	verifier(/^\/tmp\/ecluse\.[A-Za-z0-9]{6}$/.test(d), "mktemp -d modèle : " + d);
	verifier(L("!!dossierHote('bief', " + JSON.stringify(d) + ")"), "mktemp -d crée le dossier");
	verifier(t("mktemp").trim() !== tmp, "deux mktemp : deux noms");
	contient(t("mktemp /tmp/x.XX"), "too few X's", "mktemp : trop peu de X");
	// shred
	t("cp /srv/lac/donnees.csv /tmp/brut.csv");
	t("shred -u /tmp/brut.csv");
	verifier(L("!fichierHote('bief', '/tmp/brut.csv')"), "shred -u : le fichier est parti");
	// zstd : -q, -T0, -o, et le résumé sur la sortie d'erreur
	t("cp /srv/lac/donnees.csv ~/d.csv");
	egal(t("zstd -q -T0 -19 ~/d.csv"), "", "zstd -q -T0 -19 : silencieux");
	verifier(L("!!fichierHote('bief', '/home/' + JOUEUR + '/d.csv.zst')"), "zstd : d.csv.zst");
	egal(t("zstd -q -d ~/d.csv.zst -o ~/retour.csv; cat ~/retour.csv"), "id,v\n1,a\n2,b", "zstd -d -o : le fichier retrouvé, sous son nouveau nom");
	contient(t("zstd ~/retour.csv 2>&1 >/dev/null"), "retour.csv", "zstd : le résumé part sur la sortie d'erreur");
	t("cp ~/d.csv ~/e.csv");
	t("zstd -q --rm ~/e.csv");
	verifier(L("!fichierHote('bief', '/home/' + JOUEUR + '/e.csv') && !!fichierHote('bief', '/home/' + JOUEUR + '/e.csv.zst')"), "zstd --rm : l'original disparaît");
	// pv, time, parallel sur la machine
	contient(t("pv /srv/lac/gros.log > /dev/null"), "1.00GiB", "pv : la taille déclarée d'un gros fichier");
	contient(t("time ls /srv/lac"), "real\t", "time : real, user, sys");
	t("for i in 1 2 3; do echo $i > ~/h$i.csv; done");
	t("parallel zstd -q ::: ~/h1.csv ~/h2.csv ~/h3.csv");
	verifier(L("[1,2,3].every(function(i){ return !!fichierHote('bief', '/home/' + JOUEUR + '/h' + i + '.csv.zst'); })"), "parallel zstd ::: : trois fichiers compressés");
	t("parallel --joblog ~/taches.log wc -l ::: ~/h1.csv ~/absent.csv");
	egal(code(), 1, "parallel : une tâche en échec, code 1");
	contient(t("cat ~/taches.log"), "Exitval", "parallel --joblog : le journal des tâches");
	contient(L("JSON.stringify(DONNEES_VUS)"), "ionice", "les événements donnees");
	contient(L("JSON.stringify(DONNEES_VUS)"), "flock", "les événements donnees (flock)");
})();

